#include <cctype>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> names{"asha", "ravi", "mei"};

    for (auto& name : names) {                    // reference: edits the vector.
        if (!name.empty())
            name[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(name[0])));
    }
    for (const auto& name : names) {              // read-only, no copies.
        std::cout << name << '\n';
    }
    for (std::size_t i = 0; i < names.size(); ++i) {   // index loop when you need i.
        std::cout << i << ": " << names[i] << '\n';
    }
}
```

| Loop variable | Copies? | Can modify container? |
|---|---|---|
| `auto x`. | yes, each element. | no. |
| `auto& x`. | no. | yes. |
| `const auto& x`. | no. | no. |

